examples.js:
var facts = [
  'compatMode: ' + document.compatMode + ' (CSS1Compat = standards mode)',
  'doctype: ' + (document.doctype ? document.doctype.name : 'none'),
  'charset: ' + document.characterSet,
  'html lang: ' + document.documentElement.lang,
  'head child count: ' + document.head.children.length
];
var ul = document.getElementById('facts');
facts.forEach(function (f) { var li = document.createElement('li'); li.textContent = f; ul.appendChild(li); });
